// Motor de Conciliacion Forense Inteligente y Cadena de 3 Filtros Operativos
const webhookData = $('Webhook: Conciliacion Diesel').first().json.body || {};
const facturasRow = $('Postgres: Sumar Facturas Diesel').first().json || {};
const cargasRow = $('Postgres: Sumar Cargas en Obra').first().json || {};

const semana = webhookData.semana || 0;
const obraDestino = webhookData.obra_destino || 'TODAS';

const totalLitrosFactura = parseFloat(facturasRow.total_litros_factura) || 0;
const totalImporteFactura = parseFloat(facturasRow.total_importe_factura) || 0;
const totalFacturasCount = parseInt(facturasRow.total_facturas_count) || 0;
const facturasDetalle = facturasRow.facturas_detalle || [];

const totalLitrosCargas = parseFloat(cargasRow.total_litros_cargas) || 0;
const totalImporteCargas = parseFloat(cargasRow.total_importe_cargas) || 0;
const totalCargasCount = parseInt(cargasRow.total_cargas_count) || 0;
const cargasConFoto = parseInt(cargasRow.cargas_con_foto) || 0;
const cargasConHorometro = parseInt(cargasRow.cargas_con_horometro) || 0;
const cargasDetalle = cargasRow.cargas_detalle || [];

// Calculo de Balance de Combustible
const diffLitros = Math.round((totalLitrosFactura - totalLitrosCargas) * 100) / 100;
const diffImporte = Math.round((totalImporteFactura - totalImporteCargas) * 100) / 100;

let pctConsumido = 0;
if (totalLitrosFactura > 0) {
  pctConsumido = Math.round((totalLitrosCargas / totalLitrosFactura) * 1000) / 10;
}

let pctFotos = 0;
if (totalCargasCount > 0) {
  pctFotos = Math.round((cargasConFoto / totalCargasCount) * 1000) / 10;
}

let pctHorometros = 0;
if (totalCargasCount > 0) {
  pctHorometros = Math.round((cargasConHorometro / totalCargasCount) * 1000) / 10;
}

// Filtro 1: Evidencias y Auditoria Forense de Campo (Marimba / Camion 3.5 ton)
const alertasFiltro1 = [];
if (pctFotos < 90) {
  alertasFiltro1.push(`Cumplimiento de fotos cuentalitros bajo: ${pctFotos}%`);
}
if (pctHorometros < 80) {
  alertasFiltro1.push(`Cargas sin registro de horometro inicial: ${100 - pctHorometros}%`);
}

// Filtro 2: Frente de Obra (Residente)
let dictamenFrente = '';
let semaforoFrente = 'VERDE';
if (totalLitrosFactura === 0 && totalLitrosCargas > 0) {
  semaforoFrente = 'AMARILLO';
  dictamenFrente = `Consumo suministrado sin factura asignada en la semana (${totalLitrosCargas} L). Posible consumo de inventario remanente de semana previa.`;
} else if (diffLitros > 15.0) {
  semaforoFrente = 'VERDE';
  dictamenFrente = `Suministro normal. Saldo remanente de ${diffLitros} L disponible en tambos / camion 3.5 ton para continuar surtiendo maquinaria.`;
} else if (diffLitros < -15.0) {
  semaforoFrente = 'ROJO';
  dictamenFrente = `Sobregiro detectado: El consumo de maquinaria excede la factura por ${Math.abs(diffLitros)} L. Requiere revision urgente con residente.`;
} else {
  semaforoFrente = 'VERDE';
  dictamenFrente = `Conciliacion exacta. Facturado: ${totalLitrosFactura} L vs Suministrado: ${totalLitrosCargas} L. Diferencia minima de ${diffLitros} L.`;
}

// Filtro 3: Dictamen de Gobierno Corporativo
let semaforoCorp = 'VERDE';
let dictamenCorp = '';
let estadoCierre = 'PENDIENTE_FIRMAS';
if (semaforoFrente === 'ROJO' || pctFotos < 70) {
  semaforoCorp = 'ROJO';
  dictamenCorp = 'Auditoria con Banderas Rojas. Se retiene aprobacion de pago hasta solventar sobregiro o evidencias faltantes.';
} else if (semaforoFrente === 'AMARILLO' || pctFotos < 95) {
  semaforoCorp = 'AMARILLO';
  dictamenCorp = 'Auditoria con Observaciones menores. Requiere visto bueno de Residente de Obra antes del sellado corporativo.';
} else {
  semaforoCorp = 'VERDE';
  dictamenCorp = 'Auditoria Satisfactoria. Cumplimiento de politicas y saldo debidamente justificado. Listo para sellado corporativo y liberacion de pago.';
}

return {
  json: {
    semana,
    obra_destino: obraDestino,
    semaforo: semaforoCorp,
    color_semaforo: semaforoCorp === 'VERDE' ? '#10b981' : (semaforoCorp === 'AMARILLO' ? '#f59e0b' : '#ef4444'),
    mensaje: dictamenCorp,
    dictamen_tecnico: dictamenFrente,
    balance: {
      litros_facturados: totalLitrosFactura,
      litros_consumidos_obra: totalLitrosCargas,
      diferencia_litros: diffLitros,
      porcentaje_consumido: pctConsumido,
      importe_facturado: totalImporteFactura,
      importe_consumido: totalImporteCargas,
      diferencia_importe: diffImporte
    },
    cadena_filtros: {
      filtro1_campo: {
        total_cargas: totalCargasCount,
        cargas_con_foto: cargasConFoto,
        cumplimiento_fotos_pct: pctFotos,
        cumplimiento_horometros_pct: pctHorometros,
        alertas: alertasFiltro1
      },
      filtro2_residente: {
        estado: 'PENDIENTE_FIRMA',
        saldo_en_obra_lts: diffLitros,
        dictamen: dictamenFrente
      },
      filtro3_gobierno_corp: {
        estado: estadoCierre,
        semaforo: semaforoCorp,
        dictamen: dictamenCorp
      }
    },
    facturas: facturasDetalle,
    cargas: cargasDetalle,
    timestamp: new Date().toISOString()
  }
};
